return {["2020zqjj01"]={["buyPrice"]=100,["dsc"]=[[长约三尺，宽约一尺半的书案，案子两端微微翘起，整案呈月牙形状。]],["id"]=[[2020zqjj01]],["itemCanSale"]=1,["name"]=[[赏月案]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["2020zqjj02"]={["buyPrice"]=100,["dsc"]=[[高一尺的小方凳，上下均有凳面，四条凳腿略微弯曲，整个凳子呈现出球形，宛若一盏圆月。]],["id"]=[[2020zqjj02]],["itemCanSale"]=1,["name"]=[[飞月凳]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["2020zqjj03"]={["buyPrice"]=100,["dsc"]=[[这是一个落地柜，选用上等降香木制成，柜门绘秋菊四朵，上浮明月一盏。]],["id"]=[[2020zqjj03]],["itemCanSale"]=1,["name"]=[[仲秋柜]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["2020zqjj04"]={["buyPrice"]=100,["dsc"]=[[画中明月当空，一高士临流而坐，沉吟幽思，一童侍立旁边。画法高妙，意境高远。]],["id"]=[[2020zqjj04]],["itemCanSale"]=1,["name"]=[[月色秋声图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["2020zqjj05"]={["buyPrice"]=100,["dsc"]=[[以白橡木制成的镜台，通体雪白，表面光滑。上有圆框，内嵌一面铜镜，镜面平整，光可鉴人。]],["id"]=[[2020zqjj05]],["itemCanSale"]=1,["name"]=[[霜月镜]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["2024znqhome01"]={["buyPrice"]=100,["dsc"]=[[高逾七尺，巍峨挺拔，柜门之上以天工妙笔刻出山川云雾、日月星辰、花鸟走兽、鱼跃蝶舞，可谓是天地齐聚，然柜中收揽万书，自古及今，更是包罗万象。]],["id"]=[[2024znqhome01]],["itemCanSale"]=1,["name"]=[[LQS万象书柜NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[件]]},["2024znqhome02"]={["buyPrice"]=100,["dsc"]=[[案台由整块青石雕琢而成，平滑若一汪止水，案侧两脚由白檀制成，雕水波样，真好似流水徐行。]],["id"]=[[2024znqhome02]],["itemCanSale"]=1,["name"]=[[LQS止水案NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[件]]},["2024znqhome03"]={["buyPrice"]=100,["dsc"]=[[此画以繁花为景，狸奴机警可爱，蹲于花丛中，倾身卷尾，神情专明，直视舞蝶，势将扑之。此画尽展野趣，观者似能感猫之跃跃，蝶之翩翩，恍如身在其间。]],["id"]=[[2024znqhome03]],["itemCanSale"]=1,["name"]=[[LQS花下猫窥蝶NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["2024znqhome04"]={["buyPrice"]=100,["dsc"]=[[整体由白釉制成，纯白无瑕，莹润如玉，鹿眼钳有墨晶，耀如夜中星。仙鹿若自九天之外而来，正蹑云过人间。]],["id"]=[[2024znqhome04]],["itemCanSale"]=1,["name"]=[[LQS白釉游仙鹿NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[尊]]},["20bafangju1"]={["buyPrice"]=100,["dsc"]=[[以翡翠雕刻而成的骏马像，骏马两蹄扬起，仰天长嘶，其身上每一处肌肉无不活灵活现，栩栩如生。]],["id"]=[[20bafangju1]],["itemCanSale"]=1,["name"]=[[翡翠骏马]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20bafangju2"]={["buyPrice"]=100,["dsc"]=[[一幅描绘了潮水升起时海滩景象的图画。图中大海潮水汹涌，波浪滔天，绘者用笔之高妙，给人以身临其境之感。]],["id"]=[[20bafangju2]],["itemCanSale"]=1,["name"]=[[观海图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["20bafangju3"]={["buyPrice"]=100,["dsc"]=[[将枯萎的巨木对半劈开后，用数根木桩支撑制成长桌，桌面打磨平整后刷上一层薄漆，木纹清晰可见，充满了森林的气息。]],["id"]=[[20bafangju3]],["itemCanSale"]=1,["name"]=[[枯木逢春桌]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20bafangju4"]={["buyPrice"]=100,["dsc"]=[[将数根木头钉成框架后，再用晒干的玉米叶手工编织而成，坚韧而富有弹性，每年玉米丰收之后，当地的家中总会多几个类似的家具。]],["id"]=[[20bafangju4]],["itemCanSale"]=1,["name"]=[[苞米叶躺椅]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20bafangju5"]={["buyPrice"]=100,["dsc"]=[[四个一组的挂屏，以橡木为框，中间嵌入陶瓷图画，记载着春天耕地畜肥，夏天播种浇水，秋天收获打谷，冬天编织剥果的辛勤农活。]],["id"]=[[20bafangju5]],["itemCanSale"]=1,["name"]=[[四季挂屏]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20bafangju6"]={["buyPrice"]=100,["dsc"]=[[一个黑色花岗岩制成的石磨，分为上下两扇，下扇用若干石砖架起，上扇有一磨眼供粮食下漏用，两扇磨之间有安有铁轴防止掉落。]],["id"]=[[20bafangju6]],["itemCanSale"]=1,["name"]=[[花岗石磨]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20cyjiaju01"]={["buyPrice"]=100,["dsc"]=[[由上等桃木制成的长桌，用明火煅烧却不会点燃，放在屋内自有暗香袭来，被很多大宗祠在重阳节用来摆台祭祖。]],["id"]=[[20cyjiaju01]],["itemCanSale"]=1,["name"]=[[桃木台]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20cyjiaju02"]={["buyPrice"]=100,["dsc"]=[[轻便的棉布坐垫，上面染有菊花、茱萸等花朵图案，寓意长寿。登高时，人们会带上登高垫，以便累了可以坐下歇息。]],["id"]=[[20cyjiaju02]],["itemCanSale"]=1,["name"]=[[登高垫]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20cyjiaju03"]={["buyPrice"]=100,["dsc"]=[[菊花图绘粉、黄、白、紫四色折枝菊花。用笔工整，设色秀雅，画面清隽娟丽。尤其白菊直接以绢为底，铅白勾画，显得晶莹剔透，别有神韵。]],["id"]=[[20cyjiaju03]],["itemCanSale"]=1,["name"]=[[菊花图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["20cyjiaju04"]={["buyPrice"]=100,["dsc"]=[[重阳糕，因在重阳节食用而得名，亦称“花糕”。花糕蒸出时，人们喜欢保存在枣木制成的方柜中，故称“花糕柜”。]],["id"]=[[20cyjiaju04]],["itemCanSale"]=1,["name"]=[[花糕柜]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20cyjiaju05"]={["buyPrice"]=100,["dsc"]=[[以金玉制成，屏风上草书的潇洒淋漓，篆籀的拙朴婉转，金石的斑驳参入画中，而金菊自然豪放，生机酣畅。刻有“秋菊粲然白，入门无点尘。”的题词。]],["id"]=[[20cyjiaju05]],["itemCanSale"]=1,["name"]=[[金玉秋菊屏风]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20czjiaju01"]={["buyPrice"]=100,["dsc"]=[[高约一尺的唐代仕女像。仕女身穿红色绸衣，体态丰腴，右手轻贴唇边，嘴角含笑，眉目动人。]],["id"]=[[20czjiaju01]],["itemCanSale"]=1,["name"]=[[仕女含笑像]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20czjiaju02"]={["buyPrice"]=100,["dsc"]=[[用于炼丹的丹炉。此炉的独特之处在于通过机括控制风道进风量，从而控制炉内火焰大小，以达到掌握丹药炼制火候的目的。]],["id"]=[[20czjiaju02]],["itemCanSale"]=1,["name"]=[[清风炉]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20dxcjjiaju01"]={["buyPrice"]=100,["dsc"]=[[一件用翡翠雕成的白菜，翠白相间，栩栩如生。翡翠中的黄色瑕疵亦被雕成了一只蝗虫。]],["id"]=[[20dxcjjiaju01]],["itemCanSale"]=1,["name"]=[[翡翠白菜]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20dxcjjiaju02"]={["buyPrice"]=100,["dsc"]=[[一只青花瓷笔筒，上绘竹林七贤抚琴图，人物生动，活灵活现。]],["id"]=[[20dxcjjiaju02]],["itemCanSale"]=1,["name"]=[[七贤笔筒]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20dxcjjiaju03"]={["buyPrice"]=100,["dsc"]=[[以黄花梨木制成的小椅子，花纹漂亮，包浆精巧，自然散发着降香。]],["id"]=[[20dxcjjiaju03]],["itemCanSale"]=1,["name"]=[[黄花梨木椅]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20dxcjjiaju04"]={["buyPrice"]=100,["dsc"]=[[以泼墨手法绘成的骏马奔腾图，黑色线条之中点缀几抹红色，使得骏马更添神采。]],["id"]=[[20dxcjjiaju04]],["itemCanSale"]=1,["name"]=[[神骏图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["20dxcjjiaju05"]={["buyPrice"]=100,["dsc"]=[[以铁力木制成的木床，上覆白色轻纱，轻纱浮动之时若月光洒落，极具情调。]],["id"]=[[20dxcjjiaju05]],["itemCanSale"]=1,["name"]=[[月纱床]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[张]]},["20dyjiaju01"]={["buyPrice"]=100,["dsc"]=[[上刻了一张姜太公钓鱼图小床桌。旁有文字：愿者上钩，一览宏图。造此桌之人心有抱负，未得施展，于是桌上刻字，以解愁苦。]],["id"]=[[20dyjiaju01]],["itemCanSale"]=1,["name"]=[[愿者上钩桌]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20dzcdjiaju1"]={["buyPrice"]=100,["dsc"]=[[色泽青翠欲滴的瓷碗，碗口沿为八瓣葵花式，碗身浮雕栩栩如生的青龙，碗中盛水时，瓷碗内壁会浮现白云游动之景，仿若青龙正在云中遨游，当真奇特。]],["id"]=[[20dzcdjiaju1]],["itemCanSale"]=1,["name"]=[[青龙葵口碗]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20dzlqjiaju1"]={["buyPrice"]=100,["dsc"]=[[一张两尺见方的棕色小桌，桌子下有一火盆，放入木炭即可于冬日取暖。]],["id"]=[[20dzlqjiaju1]],["itemCanSale"]=1,["name"]=[[赏雪暖桌]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20dzlqjiaju2"]={["buyPrice"]=100,["dsc"]=[[一面纸屏风，共分三扇，上绘雪落青山图一副，画者笔力雄劲，观看此图如若亲临落雪的青山之中，寒冷与静谧之感铺面而来。]],["id"]=[[20dzlqjiaju2]],["itemCanSale"]=1,["name"]=[[冬雪青山屏]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20dzlqjiaju3"]={["buyPrice"]=100,["dsc"]=[[一尊做工上乘的老虎像，老虎雪白皮毛中掺杂灰色条纹，血口大张向前飞扑。捏像者技艺高超，将白虎之威尽数展现了出来。]],["id"]=[[20dzlqjiaju3]],["itemCanSale"]=1,["name"]=[[白虎像]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20dzlqjiaju4"]={["buyPrice"]=100,["dsc"]=[[一幅踏雪寻梅图，图中一文士身穿貂袍，手执书卷漫步于茫茫白雪之中，远处一枝寒梅盛开，暗香漂浮。]],["id"]=[[20dzlqjiaju4]],["itemCanSale"]=1,["name"]=[[踏雪寻梅图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20hyjiaju1"]={["buyPrice"]=100,["dsc"]=[[以紫黑檀木为框，白绸上精绣孟姜女千里送寒衣的传说，因绣技高超，使其哀怨悲凉的氛围达到极致，见者无不心生伤感。]],["id"]=[[20hyjiaju1]],["itemCanSale"]=1,["name"]=[[素绸落地屏]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20hyjiaju2"]={["buyPrice"]=100,["dsc"]=[[楠木所制的书案，两端安装外卷翘头，腿足上方设断牙，各浮雕一个自腿部横生的梅花枝，图案简朴灵动。]],["id"]=[[20hyjiaju2]],["itemCanSale"]=1,["name"]=[[傲梅翘头案]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20hyjiaju3"]={["buyPrice"]=100,["dsc"]=[[通体青花为饰，颈部倒垂蕉叶纹，腹部通景绘雪晴郊外图，画中场景正应“青烟日落更黄昏，路火千堆处处痕”的描述。]],["id"]=[[20hyjiaju3]],["itemCanSale"]=1,["name"]=[[雪晴长筒瓶]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20hyjiaju4"]={["buyPrice"]=100,["dsc"]=[[此椅与“傲梅翘头案”出自同源，背靠板镶雪梅团纹，座盘下左右两侧牙条透雕，整体造型圆婉优美，体态丰满劲健，韵味十足。]],["id"]=[[20hyjiaju4]],["itemCanSale"]=1,["name"]=[[雪梅大圈椅]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20ldjiaju01"]={["buyPrice"]=100,["dsc"]=[[上等翡翠雕成的青牛，仅有拳头大小。牛上有一童子，按孔吹笛。童子纤瘦脱尘，按在笛上的手指都瞧得分明。]],["id"]=[[20ldjiaju01]],["itemCanSale"]=1,["name"]=[[青牛童子像]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20ldjiaju02"]={["buyPrice"]=100,["dsc"]=[[“春种一粒粟，秋收万颗子。”图中一老农在烈日下锄草养田，汗流浃背。笔触灵动，意境高深。]],["id"]=[[20ldjiaju02]],["itemCanSale"]=1,["name"]=[[悯农夏耕图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20ldjiaju03"]={["buyPrice"]=100,["dsc"]=[[“采菊东篱下，悠然见南山。”此贴录有陶渊明《饮酒》一首，用字为欧体正楷，方圆兼施，笔力凝重。]],["id"]=[[20ldjiaju03]],["itemCanSale"]=1,["name"]=[[南山恭耕帖]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20ldjiaju04"]={["buyPrice"]=100,["dsc"]=[[特制的小柜子，上有小孔，底部有夹层，暗藏风道，取窖藏冰块放入，可将寒气送入柜中，用于存放食物。]],["id"]=[[20ldjiaju04]],["itemCanSale"]=1,["name"]=[[东风清凉柜]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20ldjiaju05"]={["buyPrice"]=100,["dsc"]=[[一张楠木卧榻，其中金风细雨图样却是苏州一等工匠耗时一年雕刻所成。此雕刻若是错了一笔，便要整件废弃，从头雕刻，所以极为珍贵。]],["id"]=[[20ldjiaju05]],["itemCanSale"]=1,["name"]=[[金风细雨榻]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20qxjiaju01"]={["buyPrice"]=100,["dsc"]=[[图中描绘了七夕牛郎织女鹊桥相会的场景，牛郎与织女双手相执，眼含热泪，相视而笑。二者神态惟妙惟肖，足见画者功力。]],["id"]=[[20qxjiaju01]],["itemCanSale"]=1,["name"]=[[鹊桥相会图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["20qxjiaju02"]={["buyPrice"]=100,["dsc"]=[[一面小巧铜镜，镜子外镶木框，下有小柄。镜背绘制了一副女子穿针图。]],["id"]=[[20qxjiaju02]],["itemCanSale"]=1,["name"]=[[乞巧镜]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20qxjiaju03"]={["buyPrice"]=100,["dsc"]=[[一个小木柜，白色为底，上涂七色彩漆，宛若七彩祥云。织女曾织造天上云彩，引此典故，此柜遂名织云柜。]],["id"]=[[20qxjiaju03]],["itemCanSale"]=1,["name"]=[[织云柜]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20qxjiaju04"]={["buyPrice"]=100,["dsc"]=[[以柳木制成的书案，上涂青色亮漆，据称是张生曾用过的书案。]],["id"]=[[20qxjiaju04]],["itemCanSale"]=1,["name"]=[[西厢案]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20qxjiaju05"]={["buyPrice"]=100,["dsc"]=[[以上等沉香木制成的长榻，榻两侧分别绘制了青、粉两只蝴蝶，取自梁山伯与祝英台之典故，寓意有情人终成眷属。]],["id"]=[[20qxjiaju05]],["itemCanSale"]=1,["name"]=[[蝶舞榻]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[张]]},["20s11jiaju1"]={["buyPrice"]=100,["dsc"]=[[台座上立着六片雕花屏风，线条卷曲有度，潇洒飘逸。两侧矮屏各有一个彩凤浮雕，镂中有实，庄重华贵。]],["id"]=[[20s11jiaju1]],["itemCanSale"]=1,["name"]=[[金彩漆梳妆镜台]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20s11jiaju2"]={["buyPrice"]=100,["dsc"]=[[黄花梨木制成的八仙桌，上面刻有数种花卉雕纹，百花齐放，栩栩如生。]],["id"]=[[20s11jiaju2]],["itemCanSale"]=1,["name"]=[[花开富贵八仙桌]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20s11jiaju3"]={["buyPrice"]=100,["dsc"]=[[这方玉砚似重而轻，质刚而柔，摩之寂寂无纤响，按之如小儿肌肤，温软嫩而不滑。似浑然天成，可谓无价之宝。]],["id"]=[[20s11jiaju3]],["itemCanSale"]=1,["name"]=[[赤玉砚]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20s11jiaju4"]={["buyPrice"]=100,["dsc"]=[[轿椅腿足很短，宽阔大气，椅面上有一幅财神撒元宝的画像。富贵人家出行之时，常见前后各一人肩扛台杠，主人可端坐其上。]],["id"]=[[20s11jiaju4]],["itemCanSale"]=1,["name"]=[[财神轿椅]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20shengongz01"]={["buyPrice"]=100,["dsc"]=[[以云南千年古树之木制成的书案，天然散发一种幽香，嗅入心肺，可使人心静神宁，灵感迸发。]],["id"]=[[20shengongz01]],["itemCanSale"]=0,["name"]=[[启思凝神案]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20shengongz02"]={["buyPrice"]=100,["dsc"]=[[以红木制成，高五尺，分六格。木纹清晰，有若晴空云朵。架子两侧刻有无数简笔小人，舞枪弄棒、挥剑耍刀、打拳踢腿各式姿态均有描绘。]],["id"]=[[20shengongz02]],["itemCanSale"]=1,["name"]=[[书架]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20vote3jiaju1"]={["buyPrice"]=100,["dsc"]=[[砚通体由冷玉制成，色蓝白，整体呈雪莲花状。砚面光滑，砚堂开阔，深凹月形池。雕工圆润，一眼望去，让人心无杂念，灵台清明。]],["id"]=[[20vote3jiaju1]],["itemCanSale"]=1,["name"]=[[雪莲砚]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20vote3jiaju2"]={["buyPrice"]=100,["dsc"]=[[图上绘有一年轻公子，蓝袍黑履，头戴冠帽，左手持剑直指苍天，右臂出掌覆于一块岩石之上。人物肖像神异非常，尽显豪气。]],["id"]=[[20vote3jiaju2]],["itemCanSale"]=1,["name"]=[[铁掌执剑图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20xyjiaju1"]={["buyPrice"]=100,["dsc"]=[[此图右下临水沙滩上绘乌龟一只，大龟口中吐出一股云气，化为祥云，左边有一老者捋须观日，气魄非凡。衬景是广阔的水面和沙丘，使画面平添了神秘感。]],["id"]=[[20xyjiaju1]],["itemCanSale"]=1,["name"]=[[水官神龟图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20xyjiaju2"]={["buyPrice"]=100,["dsc"]=[[屏风框架由紫檀木搭建，屏框上下雕刻夔龙纹。屏心中央画有猪、豹、兔、羊等形象，底部两侧凸出两个昂起的鹰首。万兽祈福，寓意：万寿无疆。]],["id"]=[[20xyjiaju2]],["itemCanSale"]=1,["name"]=[[万兽祈福屏]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20xyjiaju3"]={["buyPrice"]=100,["dsc"]=[[水月观音为三十三观音之一。该像头戴花蔓冠，双手于两侧垂肩而过，胸前饰缨络，下摆覆座垂于足上，神态安详宁静，犹如正观赏水中月影一般。]],["id"]=[[20xyjiaju3]],["itemCanSale"]=1,["name"]=[[水月观音铜像]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20xyjiaju4"]={["buyPrice"]=100,["dsc"]=[[一方大理石方桌，重有数百斤。方桌四周如刀斧胡乱劈刻，但桌面光洁如镜，平滑如脂。是朝中官员祭祀时，誊写祭稿的祭文台。]],["id"]=[[20xyjiaju4]],["itemCanSale"]=1,["name"]=[[祭文台]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20xyjiaju5"]={["buyPrice"]=100,["dsc"]=[[一个方形瓷瓶，通体青花装饰。瓷瓶胎体洁白坚硬，青花色泽明净艳丽，浓淡有致，层次分明。瓶身上描绘一幅山水道士图，笔法细腻灵动。]],["id"]=[[20xyjiaju5]],["itemCanSale"]=1,["name"]=[[山水道士瓶]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20xyjiaju6"]={["buyPrice"]=100,["dsc"]=[[扶手椅以黄花梨木制成，通体光素无雕饰。椅的靠背向后弯曲，扶手下凹，四条椅腿直下，看似做工简单，却极具匠心，在简朴的造型下彰显大气。]],["id"]=[[20xyjiaju6]],["itemCanSale"]=1,["name"]=[[祭官扶手椅]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20zqjiaju01"]={["buyPrice"]=100,["dsc"]=[[以白橡木制成的床榻，床体洁白如玉，光滑无比。上设轻纱垂帘，下铺绣了明月秋霜图的床褥。]],["id"]=[[20zqjiaju01]],["itemCanSale"]=1,["name"]=[[秋霜映月榻]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[张]]},["20zqjiaju02"]={["buyPrice"]=100,["dsc"]=[[上绘海升明月图的坐垫，图中明月当空，碧海生光，意境极佳，坐垫内棉花厚实，柔软易用。]],["id"]=[[20zqjiaju02]],["itemCanSale"]=1,["name"]=[[海升明月垫]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20zqjiaju03"]={["buyPrice"]=100,["dsc"]=[[高一尺，宽一尺的小丹炉，两侧通风口为圆月形状，风道极佳，下设鼓风口，炼丹时踩动机板，可鼓风进炉，使炉火更为旺盛。]],["id"]=[[20zqjiaju03]],["itemCanSale"]=1,["name"]=[[明月乘风炉]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20zyjiaju01"]={["buyPrice"]=100,["dsc"]=[[这是一个青铜铸造的蜡台，外观上是一个青面獠牙的小鬼，手中提着一个灯笼，点亮灯火后火光印在小鬼脸上，面目十分狰狞。]],["id"]=[[20zyjiaju01]],["itemCanSale"]=1,["name"]=[[鬼点灯]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["20zyjiaju02"]={["buyPrice"]=100,["dsc"]=[[一张长两丈的紫檀木供桌，桌面擦的漆黑锃亮，桌上置有香炉、蜡竿以及供品，桌下放置香皂、毛巾与水盆，以招孤魂野鬼前来享祭。]],["id"]=[[20zyjiaju02]],["itemCanSale"]=1,["name"]=[[奉魂]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["21xccdjiaju1"]={["buyPrice"]=100,["dsc"]=[[此联结字秀逸，笔力精到，多用颤笔飞白。每字之末笔，聚力飘飞，健拔峭劲，奇姿宕逸，得汉碑隶体之神韵。]],["id"]=[[21xccdjiaju1]],["itemCanSale"]=1,["name"]=[[RED寿岁隶书七言联NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["21xhlqjiaju1"]={["buyPrice"]=100,["dsc"]=[[一只三尺高的瓷瓶，上绘霜雪青竹图一幅，此瓷瓶最适用于养竹，养花草便有些大材小用了。]],["id"]=