nit"]=[[个]]},["21zyjjiaju01"]={["buyPrice"]=100,["dsc"]=[[一幅鬼气森森的画像。画中一位披头散发，满嘴烂牙的老妪站在桥上，桥下流淌着汩汩黑水，让人瘆得发慌。]],["id"]=[[21zyjjiaju01]],["itemCanSale"]=1,["name"]=[[RED孟婆像NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["21zyjjiaju02"]={["buyPrice"]=100,["dsc"]=[[这幅画的内容真叫人一言难尽......把它挂在房间里，真的不会倒霉运吗？]],["id"]=[[21zyjjiaju02]],["itemCanSale"]=1,["name"]=[[RED腐鬼噬恶图NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["21zyjjiaju03"]={["buyPrice"]=100,["dsc"]=[[一尊赤铜铸成的方鼎。铜鼎口部饰有一双拖尾卧虎，虎口大张，尖牙毕露。鼎身通体刻有饕餮纹，观之只觉煞气扑面，邪性逼人。]],["id"]=[[21zyjjiaju03]],["itemCanSale"]=1,["name"]=[[RED封灵鼎NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[尊]]},["21zyjjiaju04"]={["buyPrice"]=100,["dsc"]=[[一座妖异诡谲的鼎炉。鼎炉不知曾经炼制过什么，散出阵阵恶臭。若非极凶极恶之人，可能还不够胆使用它。]],["id"]=[[21zyjjiaju04]],["itemCanSale"]=1,["name"]=[[RED炼尸炉NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[座]]},["22anniversaryjj01"]={["buyPrice"]=100,["dsc"]=[[桌长三尺，宽三尺。由尚佳紫檀木所造，通体紫红，表面光泽饱满，桌面雕刻有八仙过海图，四周浮雕刻有群龙追珠纹样，寓有飞升仙境，苍龙相伴之意。]],["id"]=[[22anniversaryjj01]],["itemCanSale"]=1,["name"]=[[HIM紫檀八仙桌NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["22anniversaryjj02"]={["buyPrice"]=100,["dsc"]=[[太师椅通体朱红，扶手下镂空金雕浮云环月纹样，背倚处雕刻百鸟图，中部镶有圆形水墨山水画，似有仙鸟归境之美。]],["id"]=[[22anniversaryjj02]],["itemCanSale"]=1,["name"]=[[RED朱漆雕金椅NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["22anniversaryjj03"]={["buyPrice"]=100,["dsc"]=[[屏风以松木为框，涂以黑漆，正中镶嵌着由一整块墨松石雕刻而成的奇山之景。远观峰峦层叠，行云片片，流水潺潺。近看草树萋萋，林鸟群噪，好不怡然。]],["id"]=[[22anniversaryjj03]],["itemCanSale"]=1,["name"]=[[BLU墨松石素屏NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["22anniversaryjj04"]={["buyPrice"]=100,["dsc"]=[[此为法郎三足鼎，三足铸为鹤立之态，以鹤身托起鼎身，鼎身主以群青珐琅绘制仙鹤归天图，鹤形绘制精妙绝伦，栩栩如生，双耳是以纯金铸刻而成的祥云纹样灵动飘逸。]],["id"]=[[22anniversaryjj04]],["itemCanSale"]=1,["name"]=[[HIB群青珐琅鼎NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[件]]},["22zyfestivaljj01"]={["buyPrice"]=100,["dsc"]=[[这是一个用上好白梨木精雕而成的镜台，镜框雕有数十朵开放各异的梅花相互纠缠，将中心的镜面环绕其中，大有与月争辉之美。]],["id"]=[[22zyfestivaljj01]],["itemCanSale"]=1,["name"]=[[YEL暗香绕月NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["23znqjiaju01"]={["buyPrice"]=100,["dsc"]=[[这是紫檀木制成的书案，桌面嵌有一整块云石，云石上有天生天化的石纹绘制成一幅墨山水，因云石面上白润好似云雾，所以整块云石犹如一幅雾中观山画。]],["id"]=[[23znqjiaju01]],["itemCanSale"]=1,["name"]=[[HIW雾里观山案NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["23znqjiaju02"]={["buyPrice"]=100,["dsc"]=[[这是一尊鎏金财宝天王像，双盘莲花座上，财宝天王身披金甲，左手持吐宝鼠，右手持宝幢，以天狮为骑，威风凛凛。]],["id"]=[[23znqjiaju02]],["itemCanSale"]=1,["name"]=[[HIY财宝天王像NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[尊]]},["23znqjiaju03"]={["buyPrice"]=100,["dsc"]=[[这是用乌木制成的屏风，边框刻着万寿藤纹样，中间的平面镶嵌着用珠贝雕刻而成的莲花，在光照下莹莹生辉。]],["id"]=[[23znqjiaju03]],["itemCanSale"]=1,["name"]=[[HIW露水菡萏屏NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["23znqjiaju04"]={["buyPrice"]=100,["dsc"]=[[描绘了关公生擒庞德之事。画中关公长须美髯，身穿铠甲，斜披绿袍，气宇轩昂，周仓手持青龙偃月刀侍立一旁，而庞德蓬头散发被缚于柱，怒目切齿，不甘之情跃然纸上。]],["id"]=[[23znqjiaju04]],["itemCanSale"]=1,["name"]=[[HIM关公擒将图NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["25dwhome01"]={["buyPrice"]=100,["dsc"]=[[据传是唐代韩干的真迹，画上白马鬃毛飞扬，虽被系在柱子之上，也昂首嘶鸣，奋蹄欲跃。]],["id"]=[[25dwhome01]],["itemCanSale"]=1,["name"]=[[HIW照夜白图NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["25dwhome02"]={["buyPrice"]=100,["dsc"]=[[这是一个素白瓷瓶，莹润如玉，通体无纹。一支三茎野菖蒲斜插在瓶中，剑叶青碧带露，生机盎然。]],["id"]=[[25dwhome02]],["itemCanSale"]=1,["name"]=[[HIG菖蒲瓶NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["25dwhome03"]={["buyPrice"]=100,["dsc"]=[[此桌乃湘妃竹接榫所制，通体不施一钉一胶，浑若天成。其色如初春雨后新篁，青中隐黛，清雅可观。]],["id"]=[[25dwhome03]],["itemCanSale"]=1,["name"]=[[HIG青筠案NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[张]]},["25dwhome04"]={["buyPrice"]=100,["dsc"]=[[此药橱高约六尺，分九屉十八格，以柏木所制，外涂朱漆，柜门浮雕艾草缠枝纹，一开柜门则有艾香氤氲。]],["id"]=[[25dwhome04]],["itemCanSale"]=1,["name"]=[[HIG灸草柜NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["25dwhome05"]={["buyPrice"]=100,["dsc"]=[[此像取整块和田玉雕琢而成，玉质莹润含翠，透光可见水波絮纹，宛如长江激流凝于石中。匠人因材施艺，以青白处作浪，墨晕处为舟，数舟似在波澜间争渡。]],["id"]=[[25dwhome05]],["itemCanSale"]=1,["name"]=[[CYN百舸竞渡像NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["25qxhome01"]={["buyPrice"]=100,["dsc"]=[[一枚由上好的青玉雕琢而成的竹子，竹上刻有娟秀的小字“青竹沁沁，心心相印”。]],["id"]=[[25qxhome01]],["itemCanSale"]=1,["name"]=[[玉青竹]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["25qxhome02"]={["buyPrice"]=100,["dsc"]=[[铜灯一盏，灯芯若花蕊一般，点灯亮起，火光透过灯罩，如一只蝴蝶飞于花上，寓以：两情长久，春光永存。]],["id"]=[[25qxhome02]],["itemCanSale"]=1,["name"]=[[蝶恋花]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["25qxhome03"]={["buyPrice"]=100,["dsc"]=[[由一整块玉石雕琢而成的两只比翼鸟，两只鸟双宿双飞，依偎在一起。雕像整体透亮润雅，雕工细致，一根根羽毛和身上的纹理都清晰可见。]],["id"]=[[25qxhome03]],["itemCanSale"]=1,["name"]=[[比翼双飞像]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[尊]]},["25qxhome04"]={["buyPrice"]=100,["dsc"]=[[这是一面单扇的板屏，由金丝楠木为框，绸缎上绣着牛郎织女隔鹊桥相望，高超的绣技让画面惟妙惟肖，将重逢的喜悦和爱意互相交织到屏风之中。]],["id"]=[[25qxhome04]],["itemCanSale"]=1,["name"]=[[终相会]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["25qxhome05"]={["buyPrice"]=100,["dsc"]=[[此桌以紫檀木为基，通体暗红如绛霞初凝，表面面浮雕比目双鱼逐浪纹，两侧立柱雕作连理枝形，左刻“青丝”，右刻“白首”。]],["id"]=[[25qxhome05]],["itemCanSale"]=1,["name"]=[[长相守]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["25qxhome06"]={["buyPrice"]=100,["dsc"]=[[此镜台取昆仑白玉为基，莹白如新雪初积。镜缘镂雕寒梅缠枝纹，花枝间藏七枚银铃，暗合“七世姻缘”之说。台面一面蟠龙铜镜，镜钮铸成双鹤交颈状，栩栩如生。]],["id"]=[[25qxhome06]],["itemCanSale"]=1,["name"]=[[共白头]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["25znqhome01"]={["buyPrice"]=100,["dsc"]=[[玉雕通体玄青，温润凝光，是你循天然玉脉，尽思极心雕琢而成。玉上青龙夭矫，鳞爪分明，腾云而起，意气昂扬，直贯霄汉，恍若有风雷隐现其中。]],["id"]=[[25znqhome01]],["itemCanSale"]=1,["name"]=[[LIME青龙乘云NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["25znqhome02"]={["buyPrice"]=100,["dsc"]=[[此玉雕通体玄青，龙形腾跃，云气翻涌。然细看之下，龙睛处玉质微浊，神光稍敛，龙鳞边缘隐现石筋，势降一分，虽形神犹存八九，却终是功亏一篑。]],["id"]=[[25znqhome02]],["itemCanSale"]=1,["name"]=[[ALSS青龙玉雕NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["25znqhome03"]={["buyPrice"]=100,["dsc"]=[[此乃一水车模型，尽用榫卯齿轮的奇巧，引水流于暗槽中，循环不息，声若檐下细雨，幽谷清泉。置于案头，见水流不息，反生空寂，闻清音不绝，却觉万籁归宁。]],["id"]=[[25znqhome03]],["itemCanSale"]=1,["name"]=[[LSB万籁静NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["26bdghome01"]={["buyPrice"]=100,["dsc"]=[[蚊帐。钩织细腻，影影绰绰。内藏熏香，可避蚊虫、远暑气，人入账中无叮咬之扰，好梦自长。]],["id"]=[[26bdghome01]],["itemCanSale"]=1,["name"]=[[青纱蚊帱]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[顶]]},["26bdghome02"]={["buyPrice"]=100,["dsc"]=[[老樟木为胎，包浆沉润，通体鎏金缠枝云纹，形制沉敛。内贮百年樟脑与芸香，驱虫防霉，熏衣净室，亦有辟邪之意，为一方镇宅雅物。]],["id"]=[[26bdghome02]],["itemCanSale"]=1,["name"]=[[鎏金芸香樟脑盒]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["26cjfbjiaju01"]={["buyPrice"]=100,["dsc"]=[[以陈年毛竹剖篾编织而成，盘面圆润，篾纹细密。盘心可置花生、桂圆、红枣等新春果物，竹香清浅，质朴中透着乡村人家的新年气息。]],["id"]=[[26cjfbjiaju01]],["itemCanSale"]=1,["name"]=[[竹编岁盘]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["26cjfbjiaju02"]={["buyPrice"]=100,["dsc"]=[[此柜高逾五尺，分六屉十二格，以老榆木打造，外涂金漆。柜门浮雕锦鲤穿莲图，鱼身灵动，莲叶田田，拉开抽屉则有檀香淡淡溢出，纳福藏珍皆宜。]],["id"]=[[26cjfbjiaju02]],["itemCanSale"]=1,["name"]=[[吉庆有余柜]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["26cjfbjiaju03"]={["buyPrice"]=100,["dsc"]=[[此为三足铜炉，炉身鎏金，铸刻麒麟献瑞纹样，瑞兽昂首扬蹄，神态威猛灵动。炉腹中空，燃香时青烟自兽口袅袅而出，氤氲满室。]],["id"]=[[26cjfbjiaju03]],["itemCanSale"]=1,["name"]=[[鎏金瑞兽炉]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[座]]},["26cjfbjiaju04"]={["buyPrice"]=100,["dsc"]=[[素笺之上，一只金翅大鹏展翅翱翔于云海之间，下方群山连绵，旭日东升。笔墨雄浑大气，侧题 “新岁启鸿途，鹏程万里遥”，含新春吉兆，又藏江湖侠士的凌云之志。]],["id"]=[[26cjfbjiaju04]],["itemCanSale"]=1,["name"]=[[鹏程万里图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["26cjfbjiaju05"]={["buyPrice"]=100,["dsc"]=[[此屏以和田玉为骨，赤金为饰，屏面分四扇，分别雕 “岁稔年丰”“侠路安澜”“百福骈臻”“万象升平” 四景。玉质莹润通透，金纹流光溢彩，寓意着新年江湖安泰。]],["id"]=[[26cjfbjiaju05]],["itemCanSale"]=1,["name"]=[[万象升平金玉屏]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["26cjhdjiaju01"]={["buyPrice"]=100,["dsc"]=[[这是一尊由紫砂陶塑而成的罗汉像，它袒胸露腹，手持水磨禅杖，盘膝而坐，神态威严。杖身刻满梵文经咒，罗汉双目微睁，似千钧之力蕴于体内，镇宅护院，气势不凡。]],["id"]=[[26cjhdjiaju01]],["itemCanSale"]=1,["name"]=[[ZHS撼山罗汉像NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[尊]]},["26cjhdjiaju02"]={["buyPrice"]=100,["dsc"]=[[架身以玄铁混檀木锻造，沉稳厚重，横梁铸盘龙绕柱之形，龙鳞清晰可辨。专为搁置长棍、长枪而制，架角坠铜铃，棍杖入架则铃音轻响，尽显武人豪迈。]],["id"]=[[26cjhdjiaju02]],["itemCanSale"]=1,["name"]=[[ZHS盘龙镇岳架NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["26cjhdjiaju03"]={["buyPrice"]=100,["dsc"]=[[匣身以阴沉木打造，通体黝黑如墨，仅以细银丝嵌出暗纹锁扣。内分十层暗格，每层皆有磁吸机关，专储百般小巧暗器，开合无声，匣盖微启则寒光隐隐，精巧凌厉。]],["id"]=[[26cjhdjiaju03]],["itemCanSale"]=1,["name"]=[[XNS千机隐锋匣NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["26cjhdjiaju04"]={["buyPrice"]=100,["dsc"]=[[铜铸寒梅枝桠，枝头绽三朵鎏金梅花，花瓣间斜衔三枚薄刃飞刀，刀身隐于花瓣阴影之中。微风拂过，刀身轻颤，寒光一闪而逝，尽显江湖客的藏锋之道。]],["id"]=[[26cjhdjiaju04]],["itemCanSale"]=1,["name"]=[[XNS寒芒衔梅NOR]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["bagwooden001"]={["id"]=[[bagwooden001]],["name"]=[[背包木人]],["type"]=[[家具]],["unit"]=[[个]]},["bingqi001"]={["buyPrice"]=10,["dsc"]=[[一把铸造精良的青铜剑。]],["id"]=[[bingqi001]],["name"]=[[青铜剑]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[个]]},["bingqi002"]={["buyPrice"]=10,["dsc"]=[[一把精铁打造而成的大刀。]],["id"]=[[bingqi002]],["name"]=[[铁刀]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[个]]},["bingqi003"]={["buyPrice"]=10,["dsc"]=[[一根打磨得光滑的木棍。]],["id"]=[[bingqi003]],["name"]=[[木棍]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[个]]},["bingqi004"]={["buyPrice"]=10,["dsc"]=[[一把造型奇特的三尖枪。]],["id"]=[[bingqi004]],["name"]=[[三尖枪]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[个]]},["bingqi005"]={["buyPrice"]=10,["dsc"]=[[一根带着倒刺的软鞭。]],["id"]=[[bingqi005]],["name"]=[[软鞭]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[个]]},["bingqi006"]={["buyPrice"]=10,["dsc"]=[[几枚球形的铁弹子。]],["id"]=[[bingqi006]],["name"]=[[铁弹子]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[个]]},["bingqi007"]={["buyPrice"]=100,["dsc"]=[[据说是三国时孙权所珍藏的六把名剑之一。]],["id"]=[[bingqi007]],["name"]=[[紫电剑]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["bingqi008"]={["buyPrice"]=100,["dsc"]=[[汉末名将张飞初拜为新亭侯时，命铁匠取炼赤珠山铁，打造成一刀，随身佩带。]],["id"]=[[bingqi008]],["name"]=[[新亭侯]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["bingqi009"]={["buyPrice"]=100,["dsc"]=[[战国末年赵国徐夫人的名刃，形若新月，寒气四射。后燕国皇室花重金购买，交由宫廷匠师反复淬炼之后，终于成为一把见血封喉的毒刀。]],["id"]=[[bingqi009]],["name"]=[[寒月]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[个]]},["bingqi010"]={["buyPrice"]=100,["dsc"]=[[古代名厨庖丁所用菜刀，是用最普通的铁刃和最常见的木柄制成，然而由于庖丁技术高超，即便用之