e"]=[[松鹤砚]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[个]]},["dyjiaju035"]={["buyPrice"]=10,["dsc"]=[[这是熔炼炉，炉壁上刻着两个童子在菩提树下跪拜佛祖的图案，当火生起时，菩提树的树冠还会因为高温而发出一层金光，十分精巧]],["id"]=[[dyjiaju035]],["itemCanSale"]=1,["name"]=[[童子拜佛炉]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[个]]},["dyjiaju036"]={["buyPrice"]=10,["dsc"]=[[重光商会从海外佛国重金采购而得的蒲团，做工精良，用料考究，是万里无一的精品。]],["id"]=[[dyjiaju036]],["itemCanSale"]=1,["name"]=[[伽蓝垫]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[个]]},["dyjiaju037"]={["buyPrice"]=10,["dsc"]=[[这是焦尾琴，但八成是个赝品，不过考据和用料十分到位，还原度高得几可乱真、非琴道大家无法甄别。]],["id"]=[[dyjiaju037]],["itemCanSale"]=1,["name"]=[[焦尾琴]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[张]]},["dyjiaju038"]={["buyPrice"]=10,["dsc"]=[[这是一种兽面镇墓兽，从一座战国时期的楚国墓葬里出土的。镇墓兽原本是一种冥器，通常以成对的形式出现。]],["id"]=[[dyjiaju038]],["itemCanSale"]=1,["name"]=[[镇墓兽]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[个]]},["dyjiaju039"]={["buyPrice"]=10,["dsc"]=[[一尊执剑侍卫石俑，石俑面部虽有些磨损，但五官依稀可辨。据说此物有近千年历史，乃前朝盗墓行家从前朝大官墓寝耳室取出。]],["id"]=[[dyjiaju039]],["itemCanSale"]=1,["name"]=[[执剑侍卫俑]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[个]]},["dyjiaju040"]={["buyPrice"]=10,["dsc"]=[[一面金丝螺钿镜，镜面光滑如水，漆背螺钿乃为“琴翁话酒”之图，且这月白色的螺钿自不同角度泛出七彩，精美非常，故在寻常人家难得一见。]],["id"]=[[dyjiaju040]],["itemCanSale"]=1,["name"]=[[金丝螺钿镜]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[个]]},["dyjiaju041"]={["buyPrice"]=10,["dsc"]=[[一件磁刻鸳鸯鼎，鼎身雕刻鸳鸯，通体小巧，便是双手捧着把玩也可。]],["id"]=[[dyjiaju041]],["itemCanSale"]=1,["name"]=[[磁刻鸳鸯鼎]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[件]]},["dyjiaju042"]={["buyPrice"]=10,["dsc"]=[[一扇紫檀鹦鹉鎏金立屏，紫檀本就难得，且用这鎏金工艺将《戏鹦图》浮于其表就更是少见。只见立屏上的两只鹦鹉若争相互戏，似朝你飞腾而来。]],["id"]=[[dyjiaju042]],["itemCanSale"]=1,["name"]=[[紫檀鎏金立屏]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[件]]},["dyjiaju043"]={["buyPrice"]=10,["dsc"]=[[一把海青石琴桌，边缘雕刻螺旋边纹，两侧则以梅兰竹菊入画。桌上一角有三足香炉的凹痕，听闻前人好琴，日日于桌前抚弄焚香，时间一长便有了此痕。]],["id"]=[[dyjiaju043]],["itemCanSale"]=1,["name"]=[[海青石琴桌]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[个]]},["dyjiaju044"]={["buyPrice"]=10,["dsc"]=[[一把梨木雕花刺绣椅，看起来倒也寻常，只是这椅背上的绣布半嵌其中，一般除却收藏，极少有人将其摆出，因