幅]]},["zihua003"]={["buyPrice"]=10,["dsc"]=[[一幅画着栩栩如生仕女的图画。]],["id"]=[[zihua003]],["name"]=[[仕女图]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[幅]]},["zihua004"]={["buyPrice"]=10,["dsc"]=[[一幅行书写就的字帖。]],["id"]=[[zihua004]],["name"]=[[行书字帖]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[幅]]},["zihua005"]={["buyPrice"]=10,["dsc"]=[[一幅草书写就的字帖，字里行间十分狂放。]],["id"]=[[zihua005]],["name"]=[[草书字帖]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[幅]]},["zihua006"]={["buyPrice"]=10,["dsc"]=[[不知何人抄写的金刚经经文的一部分。]],["id"]=[[zihua006]],["name"]=[[金刚经文]],["salePrice"]=10,["type"]=[[家具]],["unit"]=[[幅]]},["zihua007"]={["buyPrice"]=100,["dsc"]=[[此画不知出自何人之手，但画功了得，画中人衣袂飘飘、仗剑而行，简直呼之欲出，非常传神。]],["id"]=[[zihua007]],["name"]=[[白衣剑侠图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua008"]={["buyPrice"]=100,["dsc"]=[[此画乃是刘松年所画。全作用笔变化多端，衣纹流畅罗汉头後的圆光，及三树枝柯掩映，层次分明。全画敷色妍丽，繁缛精美，皆臻绝纱。]],["id"]=[[zihua008]],["name"]=[[罗汉图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua009"]={["buyPrice"]=100,["dsc"]=[[此画乃是唐寅真作。画中线条清细，色彩艳丽清雅，体态优美，造型准确，笔简意赅，饶有意趣。]],["id"]=[[zihua009]],["name"]=[[嫦娥执桂图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua010"]={["buyPrice"]=100,["dsc"]=[[此画画功老道、浑然天成，让人感受不到一丝烟火气，细细品之，更觉得禅意盈胸。作者已经不可考。]],["id"]=[[zihua010]],["name"]=[[达摩面壁图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua011"]={["buyPrice"]=100,["dsc"]=[[此画乃李真真迹。人物脸部五官以细笔勾描，而剃净的头颅、下颚的于腮则以淡墨晕染。]],["id"]=[[zihua011]],["name"]=[[不空金刚]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua012"]={["buyPrice"]=100,["dsc"]=[[此画为周舫所作。画有六名妇女，云髻高耸，顶戴各种不同的折枝花朵，两眉画作蛾翅状，为中晚唐以后流行的贵妇造形。]],["id"]=[[zihua012]],["name"]=[[簪花仕女图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua013"]={["buyPrice"]=100,["dsc"]=[[此画乃是荆浩真迹。华中山岩质感坚硬，由左下而右上的斜线折曲繁密的排列，细腻圆熟。]],["id"]=[[zihua013]],["name"]=[[匡庐图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua014"]={["buyPrice"]=100,["dsc"]=[[此画是董源所画。此画中展现一片泽国风光，芦丛坡渚及矮丘寒林等，于远景沼泽以破墨层层渲染，而林叶以湿墨点擦成，写尽了江南水气充沛的感觉。]],["id"]=[[zihua014]],["name"]=[[寒林重汀]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua015"]={["buyPrice"]=100,["dsc"]=[[此画乃是董源真迹。这幅图卷首画几名着色小人物伫立岸边，有一红衣朝官正乘船驶来，隔着辽阔的江水，远处山峦在烟岚中起伏。]],["id"]=[[zihua015]],["name"]=[[潇湘图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua016"]={["buyPrice"]=100,["dsc"]=[[此画乃是李成真迹。画中构图采“平远”形式，前景数株松树立于烟雾之中，其后一片迷蒙分向左右两方伸展至远景山峦。松树枝干肌理、尖细松针描画细腻。]],["id"]=[[zihua016]],["name"]=[[小寒林图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua017"]={["buyPrice"]=100,["dsc"]=[[此画乃是李成真迹。画中近、中景林木，一概是枝桠虬曲、叶落尽净的“寒林”，山岩显著的轮廓线以及细密的短直皴笔。]],["id"]=[[zihua017]],["name"]=[[晴峦萧寺]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua018"]={["buyPrice"]=100,["dsc"]=[[此画乃是巨然所作。此画左上方有“宣文阁宝”印，画中山石皆以短笔披麻皴画成，轮廓线是用粗笔擦成，而自山顶到坡脚皆作小石堆叠。]],["id"]=[[zihua018]],["name"]=[[萧翼赚兰亭]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua019"]={["buyPrice"]=100,["dsc"]=[[此画是巨然真迹。“兰若”是梵话所谓的“佛寺”，这幅作品即是画一处佛院坐落的清幽山林。]],["id"]=[[zihua019]],["name"]=[[溪山兰若]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua020"]={["buyPrice"]=100,["dsc"]=[[画幅右下角行旅队后的林叶间，藏有“范宽”二字。以画构图是自山下仰望山颠的“高远”形式。]],["id"]=[[zihua020]],["name"]=[[溪山行旅]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua021"]={["buyPrice"]=100,["dsc"]=[[HIR这是米芾的行书作品。米芾的行书可谓是王羲之、颜真卿之后的又一座书法高峰。NOR]],["id"]=[[zihua021]],["name"]=[[章圣天临殿记]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua022"]={["buyPrice"]=100,["dsc"]=[[HIR这是柳公权《神策军碑》的唐拓本，可谓吉光片羽，十分珍贵。NOR]],["id"]=[[zihua022]],["name"]=[[神策军碑]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua023"]={["buyPrice"]=100,["dsc"]=[[HIR相传是张旭肚痛时自诊的一纸医案。这幅作品开头的三个字，写得还比较规正，从第四字开始，便每行一笔到底，将草书的情境表现发挥到了极致。NOR]],["id"]=[[zihua023]],["name"]=[[肚痛帖]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua024"]={["buyPrice"]=100,["dsc"]=[[此贴乃怀素所作。其笔法活泼飞动，笔下生风，“心手相师势转奇，诡形怪状翻合宜”，是一篇情愫奔腾激荡，“泼墨大写意”般的抒情之作。]],["id"]=[[zihua024]],["name"]=[[自叙帖]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua025"]={["buyPrice"]=100,["dsc"]=[[HIR由赵孟頫所作。画里描绘的是初秋时节，牧马人在荒野牧马的情景。画面中有十几匹不同造型的马，体态肥硕健壮、姿态各异。NOR]],["id"]=[[zihua025]],["name"]=[[秋郊饮马图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua026"]={["buyPrice"]=100,["dsc"]=[[HIR由赵孟坚所作。松、竹、梅画法各异，充满韵致。NOR]],["id"]=[[zihua026]],["name"]=[[岁寒三友图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua027"]={["buyPrice"]=100,["dsc"]=[[HIR此画由王冕所作，是他晚年画梅艺术臻于化境的杰作。NOR]],["id"]=[[zihua027]],["name"]=[[墨梅图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua028"]={["buyPrice"]=100,["dsc"]=[[HIR由文征明所作。此画根据屈原《九歌》的湘君、湘夫人二章而作。人物造型形象古雅，体态修长，长袖飘逸，衣裙曳地，承晋人遗风。NOR]],["id"]=[[zihua028]],["name"]=[[湘君湘夫人图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua029"]={["buyPrice"]=100,["dsc"]=[[HIR由徐渭所作。此画笔墨飞舞，纵横淋漓，虽说画葡萄，却不求形似，但趁一时之兴，痛泻心中垒块而已。NOR]],["id"]=[[zihua029]],["name"]=[[葡萄图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua030"]={["buyPrice"]=100,["dsc"]=[[HIR由宋徽宗赵佶所写的草书长卷。笔势奔放流畅，变幻莫测，一气呵成，颇为壮观，是继张旭、怀素之后的杰作。NOR]],["id"]=[[zihua030]],["name"]=[[草书千字文]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua031"]={["buyPrice"]=100,["dsc"]=[[YEL此画乃是黄公望作品。以富春江为背景，画面用墨淡雅，山和水的布置疏密得当，墨色浓淡干湿并用，极富于变化。NOR]],["id"]=[[zihua031]],["name"]=[[富春山居图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua032"]={["buyPrice"]=100,["dsc"]=[[HIM颜真卿的书法作品，被誉为“天下行书第二”，又与《兰亭序》、《黄州寒食帖》并称天下三大行书。NOR]],["id"]=[[zihua032]],["name"]=[[祭侄文稿]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua033"]={["buyPrice"]=100,["dsc"]=[[HIM苏轼行书的代表作。在书法史上影响很大，被称为“天下第三行书”，也是苏轼书法作品中的上乘。NOR]],["id"]=[[zihua033]],["name"]=[[黄州寒食帖]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua034"]={["buyPrice"]=100,["dsc"]=[[HIM王羲之的书法作品，全文只有二十八字，被誉为“二十八骊珠”，历代称为“天下法书第一”。NOR]],["id"]=[[zihua034]],["name"]=[[快雪时晴帖]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua035"]={["buyPrice"]=100,["dsc"]=[[HIM东晋顾恺之的画作，是由多个故事情节组成的类似连环画而又融会贯通的长卷，被誉为绘画始祖。NOR]],["id"]=[[zihua035]],["name"]=[[洛神赋图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]},["zihua036"]={["buyPrice"]=100,["dsc"]=[[HIM由王希孟创作的绢本画卷作品，以长卷形式，立足传统，画面细致入微，烟波浩渺的江河、层峦起伏的群山构成了一幅美妙的江南山水图，是水墨山水的大成之作。NOR]],["id"]=[[zihua036]],["name"]=[[千里江山图]],["salePrice"]=100,["type"]=[[家具]],["unit"]=[[幅]]}}000000000